#include <iostream>
#include <vector>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int w, m;
    cin >> w >> m;
    vector<int> array(101, 0);

    for (int index = 0; index <= 100; index++) {
        array[index] = m % w;
        m /= w;
    }

    int carryOver = 0;
    bool valid = true;
    for (int index = 0; index <= 100; index++) {
        array[index] += carryOver;
        carryOver = array[index] / w;
        array[index] %= w;

        if (array[index] == 0 || array[index] == 1) {
            continue;
        } else if (array[index] == w - 1) {
            carryOver = 1;
        } else {
            valid = false;
            break;
        }
    }

    cout << ((valid && carryOver != 1) ? "YES" : "NO");
    return 0;
}
